import heapq

def match(orders):
    trades = []
    orders_state = {}  # id -> dict(side, price, qty, active)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    def process_match(side, price, qty, is_market, book_heap, incoming_id):
        while qty > 0 and book_heap:
            top = book_heap[0]
            oid = top[2]
            order = orders_state.get(oid)
            if order is None or not order['active'] or order['qty'] <= 0:
                heapq.heappop(book_heap)
                continue
            if not is_market:
                if side == 'buy' and order['price'] > price:
                    break
                if side == 'sell' and order['price'] < price:
                    break
            trade_qty = min(qty, order['qty'])
            if side == 'buy':
                trades.append([incoming_id, oid, order['price'], trade_qty])
            else:
                trades.append([oid, incoming_id, order['price'], trade_qty])
            order['qty'] -= trade_qty
            qty -= trade_qty
            if order['qty'] == 0:
                order['active'] = False
                heapq.heappop(book_heap)
        return qty

    for seq, order in enumerate(orders):
        op = order[0]
        if op == 'cancel':
            oid = order[1]
            if oid in orders_state and orders_state[oid]['active']:
                orders_state[oid]['active'] = False
            continue
        elif op == 'limit':
            _, oid, side, price, qty = order
            opposite = sell_heap if side == 'buy' else buy_heap
            remaining = process_match(side, price, qty, False, opposite, oid)
            if remaining > 0:
                orders_state[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                orders_state[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}
        elif op == 'ioc':
            _, oid, side, price, qty = order
            opposite = sell_heap if side == 'buy' else buy_heap
            remaining = process_match(side, price, qty, False, opposite, oid)
            orders_state[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}
        elif op == 'market':
            _, oid, side, qty = order
            opposite = sell_heap if side == 'buy' else buy_heap
            remaining = process_match(side, None, qty, True, opposite, oid)
            orders_state[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False}

    return trades

